void main() {
  var in = new Scanner(System.in);
  System.out.print("Message: ");
  String msg = in.nextLine();
  String out = "";
  for (char c : msg.toCharArray()) {
    if (c >= 'a' && c <= 'z') {
      c = (char) ('a' + (c - 'a' + 3) % 26);
    }
    out += c;
  }
  System.out.println("Secret: " + out);
}
